import React, { HTMLAttributes } from 'react';

import { durationChipAtom } from './styles.sty.js';
import { formatResolution } from '../../../../../formatters/resolution/resolution-formatter.js';

/** @internal */
export interface DurationChipAtomProps extends HTMLAttributes<HTMLDivElement> {
  /** Start date as timestamp in milliseconds */
  from: Date;
  /** End date as timestamp in milliseconds */
  to: Date;
}

/**
 * @internal
 **/
export const DurationChipAtom = (props: DurationChipAtomProps) => {
  const { from, to, ...rest } = props;
  const resolution = formatResolution(from, to);

  return (
    <div className={durationChipAtom} {...rest}>
      {resolution}
    </div>
  );
};

DurationChipAtom['displayName'] = 'DurationChipAtom';
